int read_line(char *text, int capacity)
{
    if (fgets(text, capacity, stdin) == 0) return 0;
    char *newline = strchr(text, '\n');
    if (newline != 0) {
        *newline = '\0';
        return 1;
    }
    int ch = getchar(); // 未存到LF可能是恰好装满，也可能是末行已经结束。
    if (ch == '\n' || ch == EOF) return 1;
    while ((ch = getchar()) != '\n' && ch != EOF) {}
    return -1;
}
